prompts.user:
/ [셋업] POS별 문항 풀에서 랜덤 인덱스(*_IDX) 추출
@SET(N_IDX, "@INDEX("@N@", "@N[.]@")@", SELF)@
@SET(V_IDX, "@INDEX("@V@", "@V[.]@")@", SELF)@
@SET(ADJ_IDX, "@INDEX("@ADJ@", "@ADJ[.]@")@", SELF)@
@SET(OTH_IDX, "@INDEX("@OTH@", "@OTH[.]@")@", SELF)@

// [셋업] 추출한 문항·정답(·보기)을 JSON_test_config에 기록
@UPJ(JSON_test_config.Noun[@R_i@].problem, "@EVAL(@R_i@)@. Which of the following @POS[1]@ combines most naturally with @N[@N_IDX@]@?")@
@UPJ(JSON_test_config.Noun[@R_i@].answer, "@N_COL[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].distractor, "@N_DSTR[@EVAL("2*@INDEX("@N_DSTR@", "@N_DSTR[@N_IDX@]@")@ - 1")@:@EVAL("2*@INDEX("@N_DSTR@", "@N_DSTR[@N_IDX@]@")@")@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].original, "@N[@N_IDX@]@")@

@UPJ(JSON_test_config.Verb[@R_i@].problem, "@EVAL(@R_i@)@. Which of the following @POS[2]@ combines most naturally with @V[@V_IDX@]@?")@
@UPJ(JSON_test_config.Verb[@R_i@].answer, "@V_COL[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].distractor, "@V_DSTR[@EVAL("2*@INDEX("@V_DSTR@", "@V_DSTR[@V_IDX@]@")@ - 1")@:@EVAL("2*@INDEX("@V_DSTR@", "@V_DSTR[@V_IDX@]@")@")@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].original, "@V[@V_IDX@]@")@

@UPJ(JSON_test_config.Adjective[@R_i@].problem, "@EVAL(@R_i@)@. Which of the following @POS[3]@ combines most naturally with @ADJ[@ADJ_IDX@]@?")@
@UPJ(JSON_test_config.Adjective[@R_i@].answer, "@ADJ_COL[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].distractor, "@ADJ_DSTR[@EVAL("2*@INDEX("@ADJ_DSTR@", "@ADJ_DSTR[@ADJ_IDX@]@")@ - 1")@:@EVAL("2*@INDEX("@ADJ_DSTR@", "@ADJ_DSTR[@ADJ_IDX@]@")@")@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].original, "@ADJ[@ADJ_IDX@]@")@

@UPJ(JSON_test_config.others[@R_i@].problem, "@EVAL(@R_i@)@. Which of the following @POS[4]@ combines most naturally with @OTH[@OTH_IDX@]@?")@
@UPJ(JSON_test_config.others[@R_i@].answer, "@OTH_COL[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].distractor, "@OTH_DSTR[@EVAL("2*@INDEX("@OTH_DSTR@", "@OTH_DSTR[@OTH_IDX@]@")@ - 1")@:@EVAL("2*@INDEX("@OTH_DSTR@", "@OTH_DSTR[@OTH_IDX@]@")@")@]@")@
@UPJ(JSON_test_config.others[@R_i@].original, "@OTH[@OTH_IDX@]@")@

// [채점] 학생 응답 정오 판정 후 점수·correctness 기록 (EXACT: 정확 일치)

1. Noun
T/F boolean: @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].Noun@

Enumerated: @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@

update:
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@)@
@UPJ(JSON_test_config.Noun[@R_i@].Student_answer, "@RADIO(P_N@R_i@)@")@
